<template><view v-if="failed&&!data" class="delivery"><text class="heading">配送与自提信息</text><view>暂时没读取到，自提码等信息请稍后再试。</view><button class="ui-button" @click="load">重试</button></view><view class="delivery" v-else-if="data"><template v-if="data.method==='pickup'"><text class="heading">门店自提</text><view>{{snapshot.point?.name}}</view><view>{{snapshot.point?.address}}</view><text class="hint">{{pickupHoursText(pickupPoint)}}</text><view>{{closed?(order.status==='refunded'?'订单已全额退款，无需到店取货':'订单已取消，无需到店取货'):{pending:'等待商家备货',ready:'备货完成，请到店出示自提码',collected:'已核销取货'}[data.pickup_status]}}</view><text class="code" v-if="!closed&&data.pickup_status==='ready'">{{data.pickup_code}}</text><text v-if="!closed" class="hint">自提码用于确认交付，请仅向取货门店工作人员出示。</text></template><template v-else><text class="heading">配送与运费</text><view>{{deliveryLine(data)}}</view><view v-for="t in data.traces||[]" :key="t.id" class="trace"><view>{{t.note}}</view><text class="hint">{{formatDate(t.occurred_at)}} · 商家人工登记</text></view></template></view></template>
<script>
import {request,money} from '../services/shop'
import {pickupHoursText} from '../services/pickup-store'
import {formatDate,shippingText} from '../services/display'
export default {props:{orderId:{required:true},order:Object},data(){return{data:null,failed:false,currentPoints:[],names:{express:'快递配送',freight:'物流配送',local:'同城配送'}}},computed:{closed(){return ['refunded','cancelled'].includes(this.order?.status)},snapshot(){try{return JSON.parse(this.data?.snapshot_json||'{}')}catch{return{}}},pickupPoint(){const point=this.snapshot.point||{},current=this.currentPoints.find(p=>p.id===point.id);return current?{...point,hours:current.hours}:point}},watch:{order:{immediate:true,handler(){this.load()}}},methods:{money,pickupHoursText,formatDate,deliveryLine(d){const name=this.names[d.method]||'快递配送';if(d.fee===undefined||d.fee===null)return name;const t=shippingText(d.fee,d.method);return t?name+' · '+(t==='免运费'?t:'运费 '+t):name},async load(){this.failed=false;try{this.data=await request('/orders/'+this.orderId+'/delivery')}catch{this.data=null;this.failed=true}if(this.data?.method==='pickup'){try{this.currentPoints=(await request('/delivery-options')).points||[]}catch{this.currentPoints=[]}}}}}
</script><style scoped>
@import '../styles/component-base.css';
.delivery{margin:16px;padding:16px;border-radius:12px;background:var(--shop-surface, #fdfeff);font-size:16px;line-height:1.9}.heading{font-size:20px;font-weight:bold;display:block}.hint{font-size:13px;color:var(--shop-ink, #28546c);display:block}.trace{border-top:1px solid var(--shop-border, #d5e6ee);padding-top:10px;margin-top:10px}.code{font-size:30px;letter-spacing:5px;font-weight:bold;display:block}</style>
